(()=>{"use strict";const o={todos:[]},t=document.querySelector("#todo-input"),e=(document.querySelector("#add-btn"),document.querySelector("#todo-list"));function d(){e.innerHTML=o.todos.map((o,t)=>`\n      <li class="${o.completed?"done":""}">\n        <span onclick="window.toggleTodo(${t})">${o.text}</span>\n        <button class="form-btn" onclick="window.deleteTodo(${t})">Видалити</button>\n      </li>\n    `).join("")}window.addTodo=()=>{t.value.trim()&&(o.todos.push({text:t.value,completed:!1}),t.value="",d())},window.toggleTodo=t=>{o.todos[t].completed=!o.todos[t].completed,d()},window.deleteTodo=t=>{o.todos.splice(t,1),d()},d()})();